require_once __DIR__ . '/../../includes/admin_auth.php';require_admin();$id=valid_id($_GET['id']??$_POST['id']??null);if($id===null)redirect('index.php');$get=$pdo->prepare('SELECT * FROM gallery WHERE id=:id LIMIT 1');$get->execute(['id'=>$id]);$item=$get->fetch();if(!$item)redirect('index.php');$errors=[];if(is_post_request()){$title=post_string('title',150);$category=post_string('category',100);$description=post_string('description',3000);$status=isset($_POST['status'])?1:0;if(!verify_csrf_token($_POST['csrf_token']??null))$errors[]='Your form session expired. Please try again.';if($title==='')$errors[]='Title is required.';if($category==='')$errors[]='Category is required.';$image=upload_image('image','gallery',$errors,$item['image']);if(!$errors){$update=$pdo->prepare('UPDATE gallery SET title=:title,image=:image,category=:category,description=:description,status=:status WHERE id=:id');$update->execute(['title'=>$title,'image'=>$image,'category'=>$category,'description'=>$description?:null,'status'=>$status,'id'=>$id]);redirect('index.php');}$item=array_merge($item,['title'=>$title,'category'=>$category,'description'=>$description,'status'=>$status,'image'=>$image]);}admin_header('Edit Gallery Image','gallery/index.php');?><div class="card table-card"><div class="card-body p-4"><form method="post" enctype="multipart/form-data"><input type="hidden" name="id" value="<?=e($id)?>"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><?php if($errors):?><div class="alert alert-danger"><ul class="mb-0"><?php foreach($errors as $error):?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?><div class="row g-3"><div class="col-md-6"><label class="form-label">Title *</label><input class="form-control" name="title" value="<?=e($item['title'])?>" required></div><div class="col-md-6"><label class="form-label">Category *</label><input class="form-control" name="category" value="<?=e($item['category'])?>" required></div><div class="col-12"><label class="form-label">Replace image</label><input class="form-control" type="file" name="image" accept="image/jpeg,image/png,image/gif,image/webp"><small class="text-secondary">Leave blank to keep the current image. Maximum 5 MB.</small></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="5"><?=e($item['description'])?></textarea></div><div class="col-12"><div class="form-check"><input class="form-check-input" type="checkbox" name="status" id="status" <?=$item['status']?'checked':''?>><label class="form-check-label" for="status">Active</label></div></div></div><div class="mt-4"><button class="btn btn-primary" type="submit">Update Image</button><a class="btn btn-outline-secondary ms-2" href="index.php">Cancel</a></div></form></div></div><?php admin_footer();?>
